-- Hastkatha — product official content fields
-- Run this in Supabase: Dashboard -> SQL Editor -> New query -> paste -> Run.
-- Supports the Create Product Content / Promote My Product split: content
-- generated by "Create Product Content" is saved onto the product itself
-- (its official identity), not just logged as one-off generated text.

alter table products add column if not exists description text;
alter table products add column if not exists craft_story text;
